from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def mode(seq):
        return Counter(seq).most_common(1)[0][0]

    row_modes = [mode(row) for row in grid]
    col_modes = [mode([grid[r][c] for r in range(h)]) for c in range(w)]

    common_row_mode = mode(row_modes)
    common_col_mode = mode(col_modes)
    row_lines = [r for r, x in enumerate(row_modes) if x != common_row_mode]
    col_lines = [c for c, x in enumerate(col_modes) if x != common_col_mode]

    if len(row_lines) < 2 or len(col_lines) < 2:
        return grid

    line_colors = [row_modes[r] for r in row_lines] + [col_modes[c] for c in col_lines]
    line_color = mode(line_colors)

    interior = [
        grid[r][c]
        for r in range(h) if r not in row_lines
        for c in range(w) if c not in col_lines
    ]
    base = mode(interior)

    out = []
    for r1, r2 in zip(row_lines, row_lines[1:]):
        row = []
        for c1, c2 in zip(col_lines, col_lines[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            value = corners[0]
            row.append(value if value != line_color and all(x == value for x in corners) else base)
        out.append(row)

    # Remove the blank outer margins of the decoded matrix.
    while out and all(x == base for x in out[0]):
        out.pop(0)
    while out and all(x == base for x in out[-1]):
        out.pop()
    if out:
        while out[0] and all(row[0] == base for row in out):
            for row in out:
                row.pop(0)
        while out[0] and all(row[-1] == base for row in out):
            for row in out:
                row.pop()
    return out
